    id: 'legacy', frequency: 'hourly', agent_model: 'sonnet',
    expected_outcome: 'none', precondition: () => ({ run: false }),
  };
  assert.deepEqual(validateTaskDeclaration(decl), [], 'a member on the old vocabulary keeps running');
});
